import numpy as np
from qiskit.quantum_info import Pauli, Statevector

def state(theta, phi):
    return np.array([np.cos(theta / 2), np.exp(1j * phi) * np.sin(theta / 2)])

def bloch_vector_formula(theta, phi):
    return np.array([np.sin(theta) * np.cos(phi), np.sin(theta) * np.sin(phi), np.cos(theta)])

def bloch_vector_qiskit(vector):
    sv = Statevector(vector)
    return np.array([sv.expectation_value(Pauli(p)).real for p in "XYZ"])

cases = {"|0>": (0, 0), "|1>": (np.pi, 0), "|+>": (np.pi / 2, 0), "|->": (np.pi / 2, np.pi), "|+i>": (np.pi / 2, np.pi / 2)}
print(f"{'state':5} {'norm':>5} {'Bloch vector (x, y, z)':>26}  formula = Qiskit")
for label, (theta, phi) in cases.items():
    psi = state(theta, phi)
    formula, qiskit = bloch_vector_formula(theta, phi), bloch_vector_qiskit(psi)
    print(f"{label:5} {np.linalg.norm(psi):5.2f} {np.round(formula, 3).tolist()!s:>26}  {np.allclose(formula, qiskit)}")

psi = state(1.1, 0.7)
global_phase = np.exp(1j * 2.3) * psi
print("a global phase leaves the Bloch vector unchanged:", np.allclose(bloch_vector_qiskit(psi), bloch_vector_qiskit(global_phase)))
print("a relative phase changes it:", not np.allclose(bloch_vector_qiskit(psi), bloch_vector_qiskit(state(1.1, 0.7 + 0.5))))
